import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Sichtbarkeit von Eigenschaften","description":"","frontmatter":{"title":"Sichtbarkeit von Eigenschaften","covers":{"screens":["SCR-032"],"stories":["US-124","US-125","US-126","US-127"]}},"headers":[],"relativePath":"de/administration/property-visibility.md","filePath":"de/administration/property-visibility.md"}`),s={name:`de/administration/property-visibility.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="sichtbarkeit-von-eigenschaften" tabindex="-1">Sichtbarkeit von Eigenschaften <a class="header-anchor" href="#sichtbarkeit-von-eigenschaften" aria-label="Permalink to “Sichtbarkeit von Eigenschaften”">​</a></h1><p>Manche Eigenschaften sollen nicht alle sehen, die eine Entität lesen dürfen, etwa Investitionskosten oder eine Sicherheitseinstufung. Die Sicherheitsadministration legt für jede Eigenschaft fest, wer ihre Werte sehen und schreiben darf. Du brauchst die Rolle <code>security-admin</code> (Berechtigung <code>visibility:configure</code>); Metamodell-Administratoren können die Sichtbarkeit nicht ändern (siehe <a href="./roles-and-permissions">Rollen und Berechtigungen</a>).</p><h2 id="was-die-sichtbarkeit-bewirkt" tabindex="-1">Was die Sichtbarkeit bewirkt <a class="header-anchor" href="#was-die-sichtbarkeit-bewirkt" aria-label="Permalink to “Was die Sichtbarkeit bewirkt”">​</a></h2><ul><li><strong>Rollenbasierte</strong> Eigenschaften werden in Katalogen, im Portal und beim Schreiben von Entitäten durchgesetzt: <ul><li>Ohne Leserolle zeigt eine Spalte zur Eigenschaft ein Schloss und leere Zellen und lässt sich weder sortieren noch filtern.</li><li>Ohne Schreibrolle wird ein Batch oder eine Verbindung, die ihren Wert setzt oder entfernt, mit <code>403</code> abgelehnt.</li><li>Alte und neue Werte einer solchen Eigenschaft werden verschlüsselt im Audit-Log gespeichert.</li></ul></li><li><strong>Verbindungsbasierte</strong> Eigenschaften werden auf denselben Kanälen pro Entität durchgesetzt: <ul><li>Eine Person sieht und schreibt den Wert nur bei Entitäten, die über den gewählten Verbindungstyp mit dem Element verbunden sind, das mit ihrem Konto verknüpft ist, in beide Richtungen und über eine Verbindung (siehe <a href="#person-metatype">Der Entitätstyp von Personen</a>).</li><li>In einem Katalog zeigt die Spalte den Wert in den Zeilen solcher Entitäten und in allen anderen eine leere Zelle. Sortierung und Filter behandeln die leeren Zellen wie Einträge ohne Wert, so hängt das Ergebnis nie von einem verborgenen Wert ab.</li><li>Ohne verknüpftes Element oder für das lokale Systemadministrator-Konto verhält sich die Spalte wie eine rollenbasierte Spalte ohne Leserolle.</li><li>Ein Batch oder eine Verbindung, die den Wert einer Entität außerhalb des Bereichs oder einer im selben Batch angelegten Entität setzt oder entfernt, wird mit <code>403</code> abgelehnt; lege zuerst die Verbindung an, die den Bereich festlegt.</li><li>Eine neue oder entfernte Verbindung dieses Typs gilt ab der nächsten Anfrage.</li></ul></li></ul><h2 id="die-seite" tabindex="-1">Die Seite <a class="header-anchor" href="#die-seite" aria-label="Permalink to “Die Seite”">​</a></h2><p>Öffne <em>Sichtbarkeit von Eigenschaften</em> in der Kopfzeile. Die Seite listet jede Eigenschaft mit den Entitätstypen, die sie verwenden, ihrer Sichtbarkeit und ihrer Einschränkung; eingeschränkte Eigenschaften tragen das Badge <em>Eingeschränkt</em>. Filtere die Liste nach Name.</p>`,6),i(d,{name:`property-visibility`,alt:`Dialog für die Sichtbarkeit einer Eigenschaft mit Lese- und Schreibrollen`}),o[1]||=t(`<h2 id="person-metatype" tabindex="-1">Der Entitätstyp von Personen <a class="header-anchor" href="#person-metatype" aria-label="Permalink to “Der Entitätstyp von Personen”">​</a></h2><p>Verbindungsbasierte Sichtbarkeit geht von dem Element aus, das eine Person im Modell darstellt, zum Beispiel einem <em>Business Actor</em>. Wähle diesen Entitätstyp in <em>Entitätstyp von Personen</em> oberhalb der Liste; <em>Keiner</em> schaltet verbindungsbasierte Sichtbarkeit für alle ab. Wählbar sind nur Entitätstypen, die keine Verbindungstypen sind, und ein hier verwendeter Entitätstyp lässt sich nicht löschen. Die Änderung wird als <code>visibility.person-metatype-changed</code> ins Audit-Log geschrieben.</p><p>Solange es verbindungsbasierte Eigenschaften gibt, aber kein Entitätstyp gesetzt ist, zeigt die Seite eine Warnung: Die Werte dieser Eigenschaften sieht niemand.</p><p>Das Konto einer Person wird über die API mit ihrem Element verknüpft (siehe <a href="./identity-providers#link-an-account-to-an-element">Identity-Provider und Personen</a>). Eine Verknüpfung zählt nur, solange das Element existiert und vom gewählten Entitätstyp oder einem seiner Untertypen ist; ein Wechsel des Entitätstyps behält die Verknüpfungen, aber Verknüpfungen zu Elementen eines anderen Typs zählen nicht mehr.</p><h2 id="sichtbarkeit-andern" tabindex="-1">Sichtbarkeit ändern <a class="header-anchor" href="#sichtbarkeit-andern" aria-label="Permalink to “Sichtbarkeit ändern”">​</a></h2><p>Klicke auf den Stift einer Eigenschaft und wähle die Sichtbarkeit:</p><ul><li><strong>Öffentlich:</strong> Alle, die die Entität lesen dürfen, sehen den Wert. Das ist der Standard jeder Eigenschaft.</li><li><strong>Rollenbasiert:</strong> Nur Inhaber der gewählten Leserollen sehen den Wert, und nur Inhaber der gewählten Schreibrollen dürfen ihn ändern. Wähle mindestens eine Leserolle; jede Schreibrolle muss auch eine Leserolle sein. Ohne Schreibrolle darf niemand den Wert ändern.</li><li><strong>Verbindungsbasiert:</strong> Nur Personen, die über den gewählten Verbindungstyp mit der Entität verbunden sind, sehen und ändern den Wert, zum Beispiel eine Domänenarchitektin, die über <em>Domain Assignment</em> verbunden ist. Wählbar sind nur Verbindungstypen.</li></ul><p>Der Dialog zeigt nur die Felder der gewählten Sichtbarkeit und weist auf eine fehlende Auswahl hin, bevor er speichert. Jede Änderung wird als <code>visibility.changed</code> ins Audit-Log geschrieben; eine Änderung, die eine deiner eigenen Rollen begünstigt, wird als selbstbegünstigend markiert.</p><p>Solange ein Verbindungstyp für eine verbindungsbasierte Eigenschaft verwendet wird, braucht das Anlegen von Verbindungen dieses Typs die Berechtigung <code>visibility-scope:assign</code> (Rolle <code>security-admin</code>), damit sich niemand selbst Zugriff verschafft. Ein solcher Verbindungstyp lässt sich nicht löschen.</p><p>In der Metamodell-Konfiguration tragen eingeschränkte Eigenschaften das Badge <em>Eingeschränkt</em>, und der Dialog einer Eigenschaft zeigt ihre Sichtbarkeit nur lesend (siehe <a href="./metamodel-editing">Metamodell bearbeiten</a>).</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><p><code>GET /admin/property-visibility</code> listet die Sichtbarkeit jeder Eigenschaft mit <code>visibilityMode</code>, <code>readRoles</code>, <code>writeRoles</code>, <code>scopingConnectionType</code> und den Entitätstypen in <code>metatypes</code>.</p></li><li><p><code>PUT /admin/property-visibility</code> ändert die aufgeführten Eigenschaften in einem Schritt, zum Beispiel:</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --arg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PROPERTY_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[{propertyDefId: $id, visibilityMode: &quot;role-restricted&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  readRoles: [&quot;enterprise-architect&quot;, &quot;auditor&quot;], writeRoles: [&quot;enterprise-architect&quot;]}]&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @-</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/admin/property-visibility&quot;</span></span></code></pre></div><p>Ein ungültiger Eintrag antwortet mit <code>422</code> und dem Feld in <code>invalidFields</code>, etwa <code>[0].readRoles</code>, und nichts wird geändert.</p></li><li><p><code>GET</code> und <code>PUT /admin/property-visibility/person-metatype</code> lesen und setzen den Entitätstyp von Personen, zum Beispiel <code>{&quot;metatypeId&quot;: &quot;&lt;ID des Entitätstyps&gt;&quot;}</code>, oder <code>{&quot;metatypeId&quot;: null}</code> für keinen. Ein Verbindungstyp oder ein unbekannter Entitätstyp antwortet mit <code>422</code> und <code>metatypeId</code> in <code>invalidFields</code>.</p></li></ul><p>Alle brauchen <code>visibility:configure</code>.</p>`,13)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};